export const allPages = [
  ...guides.map((g) => ({ ...g, type: 'guide', group: 'Guides' })),
  ...apiGroups.flatMap((gr) => gr.endpoints.map((e) => ({ ...e, type: 'endpoint', group: gr.title }))),
];

export const findPage = (id) => allPages.find((p) => p.id === id);
